// Fixture identity constants (no-coincidence discipline: independent of
// every other qa fixture's names). All episodes are 120 s lavfi files, so
// the completion floor (0.9 × 120 = 108) sits ABOVE every staged ledger
// position (3, 5, 7, 9, 11, 13 — no accidental completions anywhere).
const (
	acMatrixDirA = "QA ACMatrix Alpha S01"
	acMatrixEpA  = acMatrixDirA + "/QA ACMatrix Alpha S01E01.mkv"
	acMatrixDirB = "QA ACMatrix Bravo S01"
	acMatrixEpB  = acMatrixDirB + "/QA ACMatrix Bravo S01E01.mkv"

	// The relay-stage fixtures (the dead-upstream server): same shape as the
	// relay joint's target — one serial dir, one episode per library.
	acMatrixRelayDirA = "QA ACMatrix Relay Alpha S01"
	acMatrixRelayEpA  = acMatrixRelayDirA + "/QA ACMatrix Relay Alpha S01E01.mkv"
	acMatrixRelayDirB = "QA ACMatrix Relay Bravo S01"
	acMatrixRelayEpB  = acMatrixRelayDirB + "/QA ACMatrix Relay Bravo S01E01.mkv"

	acMatrixAdminMain  = "ac-matrix-main-admin-token"
	acMatrixAdminZero  = "ac-matrix-zero-admin-token"
	acMatrixAdminRelay = "ac-matrix-relay-admin-token"

	acMatrixUserU   = "ac-matrix-user"   // the grouped user (grant {A})
	acMatrixUserV   = "ac-matrix-second" // the other-slot writer (grant {A})
	acMatrixUserZ   = "ac-matrix-scoped" // the zero-group scoped user (empty grant set)
	acMatrixGroup   = "QA ACMatrix Grants"
	acMatrixGroupB  = "QA ACMatrix Grants Relay" // the relay server's granting group
	acMatrixRelUser = "ac-matrix-relay-user"     // the relay server's grouped user
	acMatrixRelZ    = "ac-matrix-relay-scoped"   // the relay server's zero-group user

	// The staged ledger positions (the slot discriminators).
	acMatrixPosA0     = int64(7)  // slot 0 on itA (main server)
	acMatrixPosB0     = int64(11) // slot 0 on itB (main server)
	acMatrixPosBound  = int64(9)  // the bound device's write — lands in U's slot
	acMatrixPosU      = int64(3)  // the grouped user's own row (overwrites 9)
	acMatrixPosV      = int64(5)  // the second user's own row
	acMatrixPosZProbe = int64(1)  // the scoped user's refused write

	// The zero-user server's slot-0 stages (both writes land ONE legacy row;
	// the second overwrites the first — the upsert law on the legacy slot).
	acMatrixPosZeroA1 = int64(9)
	acMatrixPosZeroA2 = int64(13)
	acMatrixPosZeroB  = int64(11)

	acMatrixSearchQuery = "ac-matrix-search-probe"
	acMatrixPluginID    = "shikimori"
)

// acMatrixDeadUpstream is the relay server's upstream pin (the relay joint's
// precedent): dial tcp 127.0.0.1:9 refuses instantly — a NETWORK-class fetch
// failure, which is what hands the fetch plan to the relay queue.
const acMatrixDeadUpstream = "http://127.0.0.1:9"

// acMatrixBins builds the seven server-side binaries ONCE per test into tmp
// (all three servers boot from the same binaries).
func acMatrixBins(t *testing.T, tmp string) qaSerialServerBins {
	t.Helper()
	return qaSerialServerBins{
		server:        buildBinary(t, tmp, "ac-matrix-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "ac-matrix-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "ac-matrix-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "ac-matrix-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "ac-matrix-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "ac-matrix-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "ac-matrix-grabber", "./plugins/frame-grabber"),
	}
}

// acMatrixStartJoint boots one REAL server over the prebuilt bins with the
// given upstream pin (404-stub URL for the matrix/zero-user servers, the
// dead URL for the relay server) and creates the two serial libraries. The
// scan stays with the caller.
func acMatrixStartJoint(t *testing.T, bins qaSerialServerBins, upstream, adminToken, rootA, nameA, rootB, nameB string) *qaAcctJoint {
	t.Helper()
	tmp := t.TempDir() // the server's data dir home
	srv := qaSerialStartServer(t, bins, upstream, tmp, adminToken)
	j := &qaAcctJoint{
		srv:    srv,
		client: &http.Client{Timeout: httpTimeout},
		admin:  adminToken,
	}
	j.libA = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, adminToken, rootA, nameA)
	j.libB = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, adminToken, rootB, nameB)
	return j
}

// acMatrixWriteFixtures generates one 120 s episode per library root (the
// probeable duration every completion floor keys on — see the constants).
func acMatrixWriteFixtures(t *testing.T, rootA, epA, rootB, epB string) {
	t.Helper()
	qaAcctMedia(t, filepath.Join(rootA, epA))
	qaAcctMedia(t, filepath.Join(rootB, epB))
}

// acMatrixScanSettled scans both libraries and drains them to ready (the
// 404-stub servers only: the dead-upstream relay server never settles ready
// — its readiness signal is the enqueued relay job, polled via the DB).
func acMatrixScanSettled(t *testing.T, j *qaAcctJoint) {
	t.Helper()
	for _, lib := range []int64{j.libA, j.libB} {
		if res := scanLibrary(t, j.client, j.srv.baseURL, j.admin, lib); res.Discovered != res.Persisted {
			t.Fatalf("scan lib %d: discovered=%d persisted=%d; warnings=%v", lib, res.Discovered, res.Persisted, res.Warnings)
		}
	}
	qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.admin, j.libA, j.libB)
}

// acMatrixGround is the fixture's entity grounding: the episode ids and the
// one serial record per library, read back as the env-admin.
type acMatrixGround struct {
	itA, itB string // episode item ids
	srA, srB string // series ids
}

// acMatrixGroundEntities grounds the ids off the admin wire (the fixture's
// read-back).
func acMatrixGroundEntities(t *testing.T, j *qaAcctJoint, epA, epB string) acMatrixGround {
	t.Helper()
	g := acMatrixGround{}
	for _, it := range listItems(t, j.client, j.srv.baseURL, j.admin, j.libA) {
		if it.RelativePath == epA {
			g.itA = it.ID
		}
	}
	for _, it := range listItems(t, j.client, j.srv.baseURL, j.admin, j.libB) {
		if it.RelativePath == epB {
			g.itB = it.ID
		}
	}
	srsA := qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.libA)
	srsB := qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.libB)
	if len(srsA) == 1 {
		g.srA = srsA[0].ID
	}
	if len(srsB) == 1 {
		g.srB = srsB[0].ID
	}
	if g.itA == "" || g.itB == "" || g.srA == "" || g.srB == "" {
		t.Fatalf("fixture grounding failed: %+v", g)
	}
	return g
}

// acMatrixPutProgress asserts one PUT returns the wanted status (a thin
// law-carrying wrapper over qaAcctPutProgress).
func acMatrixPutProgress(t *testing.T, j *qaAcctJoint, token, itemID string, pos int64, want int, what string) {
	t.Helper()
	if status := qaAcctPutProgress(t, j, token, itemID, pos); status != want {
		t.Fatalf("%s: PUT progress %s pos=%d: HTTP %d, want %d", what, itemID, pos, status, want)
	}
}

// acMatrixExpectSlots asserts the EXACT (user_id → position) slot stock of
// one item (the direct store read — never the wire).
func acMatrixExpectSlots(t *testing.T, db *sql.DB, itemID string, want map[int64]int64, what string) {
	t.Helper()
	got := qaAcctProgressSlots(t, db, itemID)
	if len(got) != len(want) {
		t.Fatalf("%s: item %s progress slots = %v, want exactly %v", what, itemID, got, want)
	}
	for uid, pos := range want {
		if got[uid] != pos {
			t.Fatalf("%s: item %s progress slots = %v, want exactly %v", what, itemID, got, want)
		}
	}
}

// acMatrixKind is ONE principal kind's expected posture (the laws come from
// the shipped deltas — see the file header).
type acMatrixKind struct {
	name    string // the kind's row label
	token   string // the principal's bearer
	seesA   bool   // the visible-set law for library A
	seesB   bool   // the visible-set law for library B
	itAPos  int64  // progress/itA: the kind's expected position (−1: unspecified — see the header's non-assertions)
	itBPos  int64  // progress/itB: expected position (−1: no 200 to read, or multi-slot)
	listAll bool   // true: the progress LIST spans all slots (see-all kinds)
	ownRow  bool   // true: the kind holds an own-slot row on itA (slot-scoped kinds)
}

// acMatrixRow is one (principal kind, endpoint class, target) cell.
type acMatrixRow struct {
	kind      string
	class     string
	target    string
	method    string
	path      string
	want      int    // expected status
	wantEmpty int    // −1 n/a; 1 want 200-EMPTY listing; 0 want 200 NON-empty
	wantID    int64  // −1: no library identity assert (library detail)
	wantPos   int64  // −1: position unspecified
	wantItem  string // progress item identity on 200
	wantAlt   int    // POST /play rows only: the alternate 2xx of the acknowledgement family (see the header)
}

// acMatrixAppendKindRows appends ONE kind's 21 endpoint-class rows (the same
// class set the task line names: libraries listing + detail, summary,
// folders, series listing + detail, episodes, playback pre-mint, progress
// reads) built from the kind's law.
func acMatrixAppendKindRows(rows []acMatrixRow, j *qaAcctJoint, g acMatrixGround, k acMatrixKind) []acMatrixRow {
	libA := strconv.FormatInt(j.libA, 10)
	libB := strconv.FormatInt(j.libB, 10)
	wA, wB := http.StatusOK, http.StatusOK
	if !k.seesA {
		wA = http.StatusNotFound
	}
	if !k.seesB {
		wB = http.StatusNotFound
	}
	empty := func(sees bool) int {
		if sees {
			return 0
		}
		return 1
	}
	epA, epB := -1, -1 // episodes 200 rows are non-empty; 404 rows skip the check
	if k.seesA {
		epA = 0
	}
	if k.seesB {
		epB = 0
	}
	// POST /play's allowed path answers the ACKNOWLEDGEMENT FAMILY on the
	// real server: the cmd closure rides pack-on-play (D-8), whose enqueue
	// answers 202 queued and whose already-queued/no-op path answers 200.
	playAltA, playAltB := 0, 0
	if wA == http.StatusOK {
		playAltA = http.StatusAccepted
	}
	if wB == http.StatusOK {
		playAltB = http.StatusAccepted
	}
	return append(rows,
		acMatrixRow{k.name, "libraries_listing", "any", http.MethodGet, j.srv.baseURL + "/api/v1/libraries", http.StatusOK, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "library_detail", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/libraries/" + libA, wA, -1, j.libA, -1, "", 0},
		acMatrixRow{k.name, "library_detail", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/libraries/" + libB, wB, -1, j.libB, -1, "", 0},
		acMatrixRow{k.name, "library_summary", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/libraries/" + libA + "/summary", wA, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "library_summary", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/libraries/" + libB + "/summary", wB, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "library_folders", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/libraries/" + libA + "/folders", wA, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "library_folders", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/libraries/" + libB + "/folders", wB, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "items_listing", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/items?library=" + libA, http.StatusOK, empty(k.seesA), -1, -1, "", 0},
		acMatrixRow{k.name, "items_listing", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/items?library=" + libB, http.StatusOK, empty(k.seesB), -1, -1, "", 0},
		acMatrixRow{k.name, "series_listing", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/series?library=" + libA, http.StatusOK, empty(k.seesA), -1, -1, "", 0},
		acMatrixRow{k.name, "series_listing", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/series?library=" + libB, http.StatusOK, empty(k.seesB), -1, -1, "", 0},
		acMatrixRow{k.name, "series_detail", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/series/" + g.srA, wA, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "series_detail", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/series/" + g.srB, wB, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "episodes", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/series/" + g.srA + "/episodes", wA, epA, -1, -1, "", 0},
		acMatrixRow{k.name, "episodes", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/series/" + g.srB + "/episodes", wB, epB, -1, -1, "", 0},
		// Playback PRE-MINT (media-serving delta): hidden ≡ 404 not_found on
		// BOTH the descriptor and the mutation, before any mint/closure.
		acMatrixRow{k.name, "playback_descriptor", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/items/" + g.itA + "/playback", wA, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "playback_descriptor", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/items/" + g.itB + "/playback", wB, -1, -1, -1, "", 0},
		acMatrixRow{k.name, "playback_play", "visible", http.MethodPost, j.srv.baseURL + "/api/v1/items/" + g.itA + "/play", wA, -1, -1, -1, "", playAltA},
		acMatrixRow{k.name, "playback_play", "hidden", http.MethodPost, j.srv.baseURL + "/api/v1/items/" + g.itB + "/play", wB, -1, -1, -1, "", playAltB},
		acMatrixRow{k.name, "progress_read", "visible", http.MethodGet, j.srv.baseURL + "/api/v1/progress/" + g.itA, wA, -1, -1, k.itAPos, g.itA, 0},
		acMatrixRow{k.name, "progress_read", "hidden", http.MethodGet, j.srv.baseURL + "/api/v1/progress/" + g.itB, wB, -1, -1, k.itBPos, g.itB, 0},
	)
}

// acMatrixRunRows is THE ONE ENGINE: every row is one request, one decode,
// one assert path. 404s must carry the canonical not_found code (hidden ≡
// unknown — never 403, never a shape leak); 200s check emptiness, identity,
// and position exactly as the row law says.
func acMatrixRunRows(t *testing.T, j *qaAcctJoint, tokens map[string]string, rows []acMatrixRow) {
	t.Helper()
	for i, row := range rows {
		t.Run(fmt.Sprintf("%s/%s/%s", row.kind, row.class, row.target), func(t *testing.T) {
			var list struct {
				Items []json.RawMessage `json:"items"`
			}
			var body qaAcctAnyOrError
			var status int
			if row.wantEmpty >= 0 {
				status = doRequest(t, j.client, row.method, row.path, tokens[row.kind], nil, &list)
			} else {
				status = doRequest(t, j.client, row.method, row.path, tokens[row.kind], nil, &body)
			}
			if status != row.want && status != row.wantAlt {
				t.Fatalf("row %d (%s %s %s): HTTP %d, want %d", i, row.kind, row.class, row.target, status, row.want)
			}
			if status == http.StatusNotFound {
				if body.Error.Code != "not_found" {
					t.Fatalf("row %d (%s %s %s): error code = %q, want not_found", i, row.kind, row.class, row.target, body.Error.Code)
				}
				return
			}
			if row.wantEmpty >= 0 {
				n := len(list.Items)
				if row.wantEmpty == 1 && n != 0 {
					t.Fatalf("row %d (%s %s %s): listing holds %d rows, want 200-EMPTY (never a count or existence signal)", i, row.kind, row.class, row.target, n)
				}
				if row.wantEmpty == 0 && n == 0 {
					t.Fatalf("row %d (%s %s %s): listing empty, want the visible rows", i, row.kind, row.class, row.target)
				}
			}
			if row.wantID >= 0 && body.ID != row.wantID {
				t.Fatalf("row %d (%s %s %s): served id = %d, want %d", i, row.kind, row.class, row.target, body.ID, row.wantID)
			}
			if row.wantItem != "" && body.ItemID != row.wantItem {
				t.Fatalf("row %d (%s %s %s): served item %q, want %q", i, row.kind, row.class, row.target, body.ItemID, row.wantItem)
			}
			if row.wantPos >= 0 && body.PositionSeconds != row.wantPos {
				t.Fatalf("row %d (%s %s %s): served position %d, want %d", i, row.kind, row.class, row.target, body.PositionSeconds, row.wantPos)
			}
		})
	}
}

// acMatrixAssertLibSet asserts the listing SET for one kind (order-free).
func acMatrixAssertLibSet(t *testing.T, j *qaAcctJoint, token string, want map[int64]bool, what string) {
	t.Helper()
	got := qaAcctLibIDs(t, j, token)
	if len(got) != len(want) {
		t.Fatalf("%s: library set = %v, want exactly %v", what, got, want)
	}
	for id := range want {
		if !got[id] {
			t.Fatalf("%s: library set = %v, want exactly %v", what, got, want)
		}
	}
}

// acMatrixSetBlock asserts the resolved SETS per kind: the library listing
// set (the grant union / see-all) and the progress-list item set (the
// own-slot law on the list surface).
func acMatrixSetBlock(t *testing.T, j *qaAcctJoint, kinds []acMatrixKind, g acMatrixGround) {
	t.Helper()
	tokens := map[string]string{}
	for _, k := range kinds {
		tokens[k.name] = k.token
	}
	for _, k := range kinds {
		t.Run("sets/"+k.name, func(t *testing.T) {
			wantLibs := map[int64]bool{}
			if k.seesA {
				wantLibs[j.libA] = true
			}
			if k.seesB {
				wantLibs[j.libB] = true
			}
			acMatrixAssertLibSet(t, j, k.token, wantLibs, k.name+" library set")

			var prog struct {
				Items []struct {
					ItemID string `json:"item_id"`
				} `json:"items"`
			}
			if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/progress?limit=100", k.token, nil, &prog); status != http.StatusOK {
				t.Fatalf("%s GET /progress: HTTP %d, want 200", k.name, status)
			}
			seen := map[string]bool{}
			for _, r := range prog.Items {
				seen[r.ItemID] = true
			}
			want := map[string]bool{}
			switch {
			case k.listAll: // see-all kinds read across slots: both items
				want[g.itA] = true
				want[g.itB] = true
			case k.ownRow: // slot-scoped kinds: the own-slot rows only
				want[g.itA] = true
			default: // scoped with no rows: nothing — the other slots never surface
			}
			if len(seen) != len(want) {
				t.Fatalf("%s progress set = %v, want exactly %v", k.name, seen, want)
			}
			for id := range want {
				if !seen[id] {
					t.Fatalf("%s progress set = %v, want exactly %v", k.name, seen, want)
				}
			}
		})
	}
}

// TestAccountsACMatrix is the l6-accounts 11.5 black-box AC matrix — the
// shape and delta sources are documented in the file header.
func TestAccountsACMatrix(t *testing.T) {
	if testing.Short() {
		t.Skip("QA accounts AC matrix: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA accounts AC matrix needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	tmp := t.TempDir()
	bins := acMatrixBins(t, tmp)

	t.Run("principal_matrix", func(t *testing.T) {
		// The 404-stub upstream: derivations fail log-and-skip, rows settle
		// ready, ZERO relay jobs (the claim conjunct lives on its own server).
		up := httptest.NewServer(http.NotFoundHandler())
		t.Cleanup(up.Close)
		rootA := t.TempDir()
		rootB := t.TempDir()
		acMatrixWriteFixtures(t, rootA, acMatrixEpA, rootB, acMatrixEpB)
		j := acMatrixStartJoint(t, bins, up.URL, acMatrixAdminMain, rootA, "QA ACMatrix Alpha", rootB, "QA ACMatrix Bravo")
		acMatrixScanSettled(t, j)
		g := acMatrixGroundEntities(t, j, acMatrixEpA, acMatrixEpB)

		// The auth substrate — REAL users/groups/grants/login/bind:
		// U + V carry the granting group (libA ONLY — libB stays ungranted),
		// Z carries NO group (the empty grant set), one device is BOUND to U
		// through the real 9.3 surface, one stays UNBOUND (legacy see-all).
		userU := qaAcctCreateUser(t, j, acMatrixUserU)
		userV := qaAcctCreateUser(t, j, acMatrixUserV)
		qaAcctCreateUser(t, j, acMatrixUserZ) // the scoped user — never grouped
		group := qaAcctCreateGroup(t, j, acMatrixGroup)
		qaAcctAddMember(t, j, group, acMatrixUserU)
		qaAcctAddMember(t, j, group, acMatrixUserV)
		qaAcctGrantCollection(t, j, group, j.libA)
		sessionU := qaAcctLogin(t, j, acMatrixUserU)
		sessionV := qaAcctLogin(t, j, acMatrixUserV)
		sessionZ := qaAcctLogin(t, j, acMatrixUserZ)
		boundTok, boundCode := qaAcctPairDevice(t, j)
		unboundTok, _ := qaAcctPairDevice(t, j)
		qaAcctBindDevice(t, j, boundCode, userU)

		// THE LEDGER WRITE SCRIPT — slot isolation staged through the wire and
		// proven by the DIRECT store read: slot 0 (the env-admin's legacy
		// slot), the bound device's write riding U's slot, U's overwrite of it,
		// V's independent slot, and the two REFUSED writes (scoped-invisible
		// and hidden) leaving no row anywhere.
		db := qaAcctOpenLedger(t, j)
		acMatrixPutProgress(t, j, j.admin, g.itA, acMatrixPosA0, http.StatusOK, "stage slot0 itA")
		acMatrixPutProgress(t, j, j.admin, g.itB, acMatrixPosB0, http.StatusOK, "stage slot0 itB")
		acMatrixExpectSlots(t, db, g.itA, map[int64]int64{0: acMatrixPosA0}, "after slot-0 stage")
		acMatrixPutProgress(t, j, boundTok, g.itA, acMatrixPosBound, http.StatusOK, "bound device write")
		acMatrixExpectSlots(t, db, g.itA, map[int64]int64{0: acMatrixPosA0, userU: acMatrixPosBound}, "bound device write rides U's slot")
		acMatrixPutProgress(t, j, sessionU, g.itA, acMatrixPosU, http.StatusOK, "user U write")
		acMatrixPutProgress(t, j, sessionV, g.itA, acMatrixPosV, http.StatusOK, "user V write")
		acMatrixExpectSlots(t, db, g.itA, map[int64]int64{0: acMatrixPosA0, userU: acMatrixPosU, userV: acMatrixPosV}, "three independent slots")
		qaAcctRequireSlots(t, "staging (all positions sub-threshold)", g.itA, qaAcctWatchedSlots(t, db, g.itA)) // want NONE
		acMatrixPutProgress(t, j, sessionZ, g.itA, acMatrixPosZProbe, http.StatusNotFound, "scoped user on invisible item")
		acMatrixPutProgress(t, j, sessionU, g.itB, acMatrixPosZProbe, http.StatusNotFound, "user on hidden-library item")
		acMatrixExpectSlots(t, db, g.itA, map[int64]int64{0: acMatrixPosA0, userU: acMatrixPosU, userV: acMatrixPosV}, "refused writes wrote nothing (itA)")
		acMatrixExpectSlots(t, db, g.itB, map[int64]int64{0: acMatrixPosB0}, "refused writes wrote nothing (itB)")

		// THE TABLE — 5 kinds × 21 rows, ONE engine. Laws: env-admin and the
		// unbound device see all ("Legacy principals keep see-all"), the
		// session and the BOUND device see the grant union {A} exactly
		// ("The union of groups is the visible set" / "Binding re-scopes the
		// device"), the scoped zero-group user sees NOTHING (default-hidden,
		// the empty grant set → the fail-closed floor).
		kinds := []acMatrixKind{
			{name: "env_admin", token: j.admin, seesA: true, seesB: true, itAPos: -1, itBPos: acMatrixPosB0, listAll: true},
			{name: "session", token: sessionU, seesA: true, seesB: false, itAPos: acMatrixPosU, itBPos: -1, ownRow: true},
			{name: "scoped_user", token: sessionZ, seesA: false, seesB: false, itAPos: -1, itBPos: -1},
			{name: "unbound_device", token: unboundTok, seesA: true, seesB: true, itAPos: -1, itBPos: acMatrixPosB0, listAll: true},
			{name: "bound_device", token: boundTok, seesA: true, seesB: false, itAPos: acMatrixPosU, itBPos: -1, ownRow: true},
		}
		tokens := map[string]string{}
		var rows []acMatrixRow
		for _, k := range kinds {
			tokens[k.name] = k.token
			rows = acMatrixAppendKindRows(rows, j, g, k)
		}
		acMatrixRunRows(t, j, tokens, rows)
		acMatrixSetBlock(t, j, kinds, g)

		// THE ISOLATION TAIL — the third slot's own reader: V reads back
		// exactly her own row (5), never slot 0's 7, never U's 3.
		var vProg qaAcctAnyOrError
		if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/progress/"+g.itA, sessionV, nil, &vProg); status != http.StatusOK || vProg.PositionSeconds != acMatrixPosV {
			t.Fatalf("session V progress read: HTTP %d pos %d, want 200 pos %d (own slot vs slot 0 vs U's slot)", status, vProg.PositionSeconds, acMatrixPosV)
		}
		acMatrixExpectSlots(t, db, g.itA, map[int64]int64{0: acMatrixPosA0, userU: acMatrixPosU, userV: acMatrixPosV}, "final slot stock")
	})

	t.Run("zero_user_legacy_mode", func(t *testing.T) {
		// A server booted with NO users ever created (the fixture boots one —
		// this subtest simply never creates any): the runtime legacy collapse
		// answers EVERY principal today's scope (accounts delta "Zero users
		// means today"). The same 21-class engine runs over the two
		// principals that can exist here — both see-all, both writing the
		// user_id=0 legacy slot.
		up := httptest.NewServer(http.NotFoundHandler())
		t.Cleanup(up.Close)
		rootA := t.TempDir()
		rootB := t.TempDir()
		acMatrixWriteFixtures(t, rootA, acMatrixEpA, rootB, acMatrixEpB)
		j := acMatrixStartJoint(t, bins, up.URL, acMatrixAdminZero, rootA, "QA ACMatrix Zero Alpha", rootB, "QA ACMatrix Zero Bravo")
		acMatrixScanSettled(t, j)
		g := acMatrixGroundEntities(t, j, acMatrixEpA, acMatrixEpB)
		devTok, _ := qaAcctPairDevice(t, j)

		// The LEGACY-SLOT write script: both principals upsert into slot 0 —
		// ONE row per item, the second write overwriting the first (the
		// upsert law on the legacy slot), and the direct read proves no
		// per-user slot ever appears.
		db := qaAcctOpenLedger(t, j)
		acMatrixPutProgress(t, j, j.admin, g.itA, acMatrixPosZeroA1, http.StatusOK, "zero-user admin write")
		acMatrixPutProgress(t, j, devTok, g.itA, acMatrixPosZeroA2, http.StatusOK, "zero-user device write")
		acMatrixExpectSlots(t, db, g.itA, map[int64]int64{0: acMatrixPosZeroA2}, "zero-user legacy slot (single row, overwritten)")
		acMatrixPutProgress(t, j, devTok, g.itB, acMatrixPosZeroB, http.StatusOK, "zero-user device write itB")
		acMatrixExpectSlots(t, db, g.itB, map[int64]int64{0: acMatrixPosZeroB}, "zero-user legacy slot itB")

		kinds := []acMatrixKind{
			{name: "env_admin", token: j.admin, seesA: true, seesB: true, itAPos: acMatrixPosZeroA2, itBPos: acMatrixPosZeroB, listAll: true},
			{name: "unbound_device", token: devTok, seesA: true, seesB: true, itAPos: acMatrixPosZeroA2, itBPos: acMatrixPosZeroB, listAll: true},
		}
		tokens := map[string]string{}
		var rows []acMatrixRow
		for _, k := range kinds {
			tokens[k.name] = k.token
			rows = acMatrixAppendKindRows(rows, j, g, k)
		}
		acMatrixRunRows(t, j, tokens, rows)
		acMatrixSetBlock(t, j, kinds, g)

		// THE LOGIN REFUSAL — no users exist, so every login attempt answers
		// the uniform authentication failure (the delta's uniform-401 law
		// observed from the zero-user side; no enumeration, identical bodies).
		rawA, rawB := json.RawMessage{}, json.RawMessage{}
		if status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/auth/login", "",
			map[string]string{"username": "ac-matrix-ghost", "password": "whatever-1"}, &rawA); status != http.StatusUnauthorized {
			t.Fatalf("zero-user login attempt 1: HTTP %d, want 401", status)
		}
		if status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/auth/login", "",
			map[string]string{"username": "ac-matrix-phantom", "password": "whatever-2"}, &rawB); status != http.StatusUnauthorized {
			t.Fatalf("zero-user login attempt 2: HTTP %d, want 401", status)
		}
		if string(rawA) != string(rawB) {
			t.Fatalf("zero-user login bodies differ: %s vs %s (the uniform 401 body)", string(rawA), string(rawB))
		}
	})

	t.Run("relay_claim_scoping", func(t *testing.T) {
		// The dead-upstream server: the REAL derivation chain enqueues two
		// library-backed enrich jobs (relayed handoff, 11.1's production
		// entry), and the REAL identify search passthrough enqueues the
		// 0-library search job. The claim sequence then walks the conjunct
		// over the LIVE pool (client-relayed-fetch delta "An invisible
		// library's job is never handed out" / "Nothing to claim").
		rootA := t.TempDir()
		rootB := t.TempDir()
		qaAcctMedia(t, filepath.Join(rootA, acMatrixRelayEpA))
		qaAcctMedia(t, filepath.Join(rootB, acMatrixRelayEpB))
		j := acMatrixStartJoint(t, bins, acMatrixDeadUpstream, acMatrixAdminRelay, rootA, "QA ACMatrix Relay Alpha", rootB, "QA ACMatrix Relay Bravo")
		for _, lib := range []int64{j.libA, j.libB} {
			if res := scanLibrary(t, j.client, j.srv.baseURL, j.admin, lib); res.Discovered != res.Persisted {
				t.Fatalf("scan lib %d: discovered=%d persisted=%d; warnings=%v", lib, res.Discovered, res.Persisted, res.Warnings)
			}
		}
		db := qaAcctOpenLedger(t, j)
		acMatrixWaitRelayPending(t, db, qaSerialDrainTimeout, 2, 0)

		// The search passthrough: fired as the admin with a SHORT client
		// timeout — the production closure enqueues the purpose=search,
		// library_id=0 job, then holds up to relaySearchBudget waiting for a
		// claimant. The test abandons the request (its outcome is out of
		// scope) and asserts only the pending job row it leaves.
		go func() {
			req, err := http.NewRequest(http.MethodGet,
				j.srv.baseURL+"/api/v1/admin/sources/"+acMatrixPluginID+"/search?query="+acMatrixSearchQuery, nil)
			if err != nil {
				return
			}
			req.Header.Set("Authorization", "Bearer "+j.admin)
			client := &http.Client{Timeout: 3 * time.Second}
			_, _ = client.Do(req) // fire-and-forget: the job row is the assertion
		}()
		acMatrixWaitRelayPending(t, db, qaSerialDrainTimeout, 2, 1)

		// The claimant substrate: a grant-carrying user (libA), a zero-group
		// scoped user, a device BOUND to the grouped user, an UNBOUND device.
		userU := qaAcctCreateUser(t, j, acMatrixRelUser)
		qaAcctCreateUser(t, j, acMatrixRelZ)
		group := qaAcctCreateGroup(t, j, acMatrixGroupB)
		qaAcctAddMember(t, j, group, acMatrixRelUser)
		qaAcctGrantCollection(t, j, group, j.libA)
		sessionU := qaAcctLogin(t, j, acMatrixRelUser)
		sessionZ := qaAcctLogin(t, j, acMatrixRelZ)
		boundTok, boundCode := qaAcctPairDevice(t, j)
		unboundTok, _ := qaAcctPairDevice(t, j)
		qaAcctBindDevice(t, j, boundCode, userU)

		// THE CLAIM SEQUENCE — every step's outcome asserted on the wire AND
		// on the direct store read:
		//
		//  1. scoped (zero grants) → ONLY the 0-job (library_id = 0), though
		//     it is the pool's NEWEST row — the empty-set narrowing is
		//     structurally narrower, never the empty clause.
		descZ := acMatrixClaim(t, j, sessionZ, http.StatusOK)
		if descZ.Purpose != "search" {
			t.Fatalf("scoped claim purpose = %q, want search (the only 0-job; library-backed rows must never cross)", descZ.Purpose)
		}
		acMatrixAssertClaimRow(t, db, descZ.ID, "search", 0, acMatrixHash(sessionZ), "scoped claim")
		// 2. the grant-carrying session → its OWN library's enrich job — the
		//    invisible libB job skipped even if it is the older row.
		descU := acMatrixClaim(t, j, sessionU, http.StatusOK)
		if descU.Purpose != "enrich" {
			t.Fatalf("session claim purpose = %q, want enrich", descU.Purpose)
		}
		acMatrixAssertClaimRow(t, db, descU.ID, "enrich", j.libA, acMatrixHash(sessionU), "session claim")
		// 3. the bound device (rides U's grants {A}) → only libB remains and
		//    it is invisible → nothing claimable (204).
		acMatrixClaim(t, j, boundTok, http.StatusNoContent)
		// 4. the scoped user again → library-backed-only pool under the
		//    library_id = 0 conjunct → nothing claimable (204).
		acMatrixClaim(t, j, sessionZ, http.StatusNoContent)
		// 5. the unbound device (see-all) → the parked invisible job IS
		//    handed out — it remains claimable by principals whose visible
		//    set carries that library.
		descDev := acMatrixClaim(t, j, unboundTok, http.StatusOK)
		if descDev.Purpose != "enrich" {
			t.Fatalf("unbound claim purpose = %q, want enrich", descDev.Purpose)
		}
		acMatrixAssertClaimRow(t, db, descDev.ID, "enrich", j.libB, acMatrixHash(unboundTok), "unbound claim")
		// 6. the env-admin → the pool is empty → nothing claimable (204).
		acMatrixClaim(t, j, j.admin, http.StatusNoContent)

		// FINAL STOCK: three rows, each claimed by exactly the principal that
		// was handed it (the SHA-256 bearer hash — the same credential the
		// result route re-derives), none done, none pending.
		acMatrixAssertClaimRow(t, db, descZ.ID, "search", 0, acMatrixHash(sessionZ), "final stock (search)")
		acMatrixAssertClaimRow(t, db, descU.ID, "enrich", j.libA, acMatrixHash(sessionU), "final stock (libA)")
		acMatrixAssertClaimRow(t, db, descDev.ID, "enrich", j.libB, acMatrixHash(unboundTok), "final stock (libB)")
	})
}

// acMatrixClaim POSTs /relay/claim as token and asserts the wanted status.
// On 200 the descriptor is decoded and returned (the plan must be non-empty
// — a descriptor without a fetch plan is not a handout); on 204 the zero
// descriptor is returned.
func acMatrixClaim(t *testing.T, j *qaAcctJoint, token string, want int) acMatrixClaimDescriptor {
	t.Helper()
	var desc acMatrixClaimDescriptor
	if status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/relay/claim", token, nil, &desc); status != want {
		t.Fatalf("POST /relay/claim: HTTP %d, want %d", status, want)
	}
	if want == http.StatusOK {
		if desc.ID == 0 {
			t.Fatalf("claim descriptor: zero id served (%+v)", desc)
		}
		if len(desc.Plan) == 0 {
			t.Fatalf("claim %d: empty plan served", desc.ID)
		}
	}
	return desc
}

// acMatrixClaimDescriptor is the QA-local decode of the claim descriptor
// ({id, purpose, plan} — the api projection of the claimed relay job).
type acMatrixClaimDescriptor struct {
	ID      int64             `json:"id"`
	Purpose string            `json:"purpose"`
	Plan    []json.RawMessage `json:"plan"`
}

// acMatrixHash is the relay principal identity: the SHA-256 hex of the raw
// bearer credential (api's principalHash recipe — the only form a claim
// stamp takes at rest).
func acMatrixHash(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

// acMatrixRelayRow is one relay_jobs row read directly from the server's
// SQLite (the pool's ground truth — the wire only ever shows descriptors).
type acMatrixRelayRow struct {
	ID      int64
	Purpose string
	LibID   int64
	State   string
	Hash    string
}

// acMatrixRelayRows reads every relay_jobs row, id order.
func acMatrixRelayRows(t *testing.T, db *sql.DB) []acMatrixRelayRow {
	t.Helper()
	rows, err := db.Query(`SELECT id, purpose, library_id, state, claim_principal_hash FROM relay_jobs ORDER BY id`)
	if err != nil {
		t.Fatalf("read relay_jobs: %v", err)
	}
	defer rows.Close()
	out := []acMatrixRelayRow{}
	for rows.Next() {
		var r acMatrixRelayRow
		if err := rows.Scan(&r.ID, &r.Purpose, &r.LibID, &r.State, &r.Hash); err != nil {
			t.Fatalf("scan relay_jobs: %v", err)
		}
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("read relay_jobs: %v", err)
	}
	return out
}

// acMatrixWaitRelayPending polls the direct store read until the pending
// pool holds exactly wantEnrich enrich jobs and wantSearch search jobs (the
// dead-upstream derivation's enqueues are async — the pool is the readiness
// signal).
func acMatrixWaitRelayPending(t *testing.T, db *sql.DB, timeout time.Duration, wantEnrich, wantSearch int) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for {
		gotEnrich, gotSearch := 0, 0
		for _, r := range acMatrixRelayRows(t, db) {
			if r.State == "pending" {
				switch r.Purpose {
				case "enrich":
					gotEnrich++
				case "search":
					gotSearch++
				}
			}
		}
		if gotEnrich == wantEnrich && gotSearch == wantSearch {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("relay pool never reached enrich=%d search=%d pending within %s; rows=%+v",
				wantEnrich, wantSearch, timeout, acMatrixRelayRows(t, db))
		}
		time.Sleep(probeInterval)
	}
}

// acMatrixAssertClaimRow asserts one relay job's claimed posture directly
// from the store: purpose, library_id, and the claiming principal's hash.
func acMatrixAssertClaimRow(t *testing.T, db *sql.DB, id int64, purpose string, libID int64, hash, what string) {
	t.Helper()
	for _, r := range acMatrixRelayRows(t, db) {
		if r.ID != id {
			continue
		}
		if r.State != "claimed" {
			t.Fatalf("%s: job %d state = %q, want claimed", what, id, r.State)
		}
		if r.Purpose != purpose || r.LibID != libID {
			t.Fatalf("%s: job %d = %s/lib %d, want %s/lib %d", what, id, r.Purpose, r.LibID, purpose, libID)
		}
		if r.Hash != hash {
			t.Fatalf("%s: job %d claim hash = %q, want %q (the presenting principal)", what, id, r.Hash, hash)
		}
		return
	}
	t.Fatalf("%s: relay job %d not found in %+v", what, id, acMatrixRelayRows(t, db))
}
